  right:"Correcto.",notQuite:"No del todo.",belongs:"Es {b}.",nOf:"{n} de {of}",
  scenario:"Situación",qsLabel:"Las situaciones",score:"Puntaje",answered:"respondidas",toGo:"por responder",good:"Buena decisión.",explore:"Explora el lab:",
  results:"Ver cómo te fue",nextQ:"Siguiente situación →",fromFilm:"de",
  allFilms:"Todas las películas",filter:"Mostrar las situaciones de",stillOpen:"{n} sin responder",filmN:"Película {n} de {of}",placed:"{n} de {of} listas",firstTry:"bien al primer intento",
